examples.template:
@OptIn(ExperimentalMaterial3AdaptiveApi::class)
NavigableListDetailPaneScaffold(
    navigator = navigator,
    modifier = Modifier.height(320.dp),
    listPane = {
        AnimatedPane {
            LazyColumn {
                items(items = items, key = { it }) { item ->
                    MonarchListRow(
                        headlineContent = { MonarchText(text = item) },
                        divider = true,
                        onClick = {
                            scope.launch { navigator.navigateTo(ListDetailPaneScaffoldRole.Detail, item) }
                        },
                    )
                }
            }
        }
    },
    detailPane = {
        AnimatedPane {
            val item = navigator.currentDestination?.contentKey
            if (item == null) {
                MonarchEmptyState(title = {{empty.title}}, message = {{empty.description}})
            } else {
                MonarchText(text = item, modifier = Modifier.padding(MonarchTheme.spacing.space4))
            }
        }
    },
)

